using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using TMPro;
using UnityEditor;
using UnityEngine;

namespace LogicLegends.OpenArchive.Topics.Editor
{
    public static class ArchiveMethodChecks
    {
        [Serializable]sealed class Result{public string name;public bool passed;}
        [Serializable]sealed class Report{public bool passed;public string checkedUtc,scope="Unity Editor: five original Proof Forge stages through native Book, method altar, tablet, socket and check controls. Timeout fixtures age deadlines; physical Android is separate.";public List<Result> checks=new List<Result>();public List<string> errors=new List<string>();}
        static readonly Stack<IEnumerator> stack=new Stack<IEnumerator>();static Report report;static ArchiveTopicSession session;static ArchiveTopicStation station;static ArchiveMethodPresentation art;static ArchiveMethodUI ui;
        static bool active,oldHunting;static double next;static GameObject restriction;
        public static string Status{get;private set;}="Idle";
        static ArchiveStationState State=>session.State.stations[4];
        [MenuItem("Tools/Logic Legends/Open Archive/Topics/Test T5 Proof Forge (Play Mode)")]
        public static void Begin(){
            if(!Application.isPlaying||Photon.Pun.PhotonNetwork.InRoom||active)throw new InvalidOperationException("Offline Play Mode required.");session=ArchiveTopicSession.Current;station=session.stations[4];art=station.GetComponent<ArchiveMethodPresentation>();ui=ArchiveTopicUI.Current.GetComponent<ArchiveMethodUI>();
            report=new Report{checkedUtc=DateTime.UtcNow.ToString("o")};stack.Clear();stack.Push(Flow());next=0;oldHunting=session.hunting.enabled;session.hunting.Request(LogicLegends.OpenArchive.Hunting.KhezuCommand.Sleep);session.hunting.enabled=false;active=true;Application.logMessageReceived+=Log;EditorApplication.update+=Tick;
        }
        static void Log(string message,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)report.errors.Add(message);}
        static void Tick(){if(!active)return;try{EditorApplication.QueuePlayerLoopUpdate();if(EditorApplication.timeSinceStartup<next)return;if(!Application.isPlaying)throw new InvalidOperationException("Play Mode stopped.");if(stack.Count==0){Finish(true);return;}var flow=stack.Peek();if(!flow.MoveNext()){stack.Pop();return;}if(flow.Current is IEnumerator child)stack.Push(child);else next=EditorApplication.timeSinceStartup+(flow.Current is float delay?delay:0);}catch(Exception e){report.errors.Add(Status+": "+e);Finish(false);}}
        static void Check(bool passed,string name){report.checks.Add(new Result{name=name,passed=passed});if(!passed)throw new InvalidOperationException(name);}
        static void Move(Vector3 p)=>ArchiveTopicPlayChecks.MoveTo(station,p);
        static void Book(){Move(ArchiveTopicStation.BookPosition+Vector3.back*1.7f);station.points.First(p=>p.role==ArchivePointRole.Book).Interact();}
        static IEnumerator Method(int method){Move(ArchiveMethodPresentation.MethodPosition(method));station.points.First(p=>p.role==ArchivePointRole.Select&&p.index==method).Interact();yield return .08f;Check(State.selection==method,"Hand selects "+ArchiveMethodPresentation.MethodName(method)+" at its altar");}
        static IEnumerator Place(int item,int slot){
            var q=session.Question(4);Move(station.CurrentItemPosition(item,q,State));station.points.First(p=>p.role==ArchivePointRole.Item&&p.index==item).Interact();yield return .055f;Check(State.carries.Any(c=>c.actor==-1&&c.item==item),"Hand picks existing "+q.items[item]);
            Move(station.SlotPosition(slot,q));station.points.First(p=>p.role==ArchivePointRole.Slot&&p.index==slot).Interact();yield return .055f;Check(State.placements[slot]==item&&State.carries.Count==0,"Hand places "+q.items[item]+" in "+q.slots[slot]);
        }
        static IEnumerator Arrange(int[] answer){for(int i=0;i<answer.Length;i++)if(State.placements[i]!=answer[i])yield return Place(answer[i],i);}
        static IEnumerator Submit(){Move(Vector3.zero);ui.CheckButton.onClick.Invoke();yield return .18f;}
        static IEnumerator Preview(string file,bool reading){Move(new Vector3(0,0,6.1f));Player.LocalInstance.transform.rotation=station.transform.rotation*Quaternion.Euler(0,180,0);var look=Player.LocalInstance.GetComponentInChildren<CameraTargetController>();if(look!=null)look.SetViewAngles(27,station.transform.eulerAngles.y+180);if(reading)ArchiveTopicUI.Current.Open(station);else ArchiveTopicUI.Current.Close();yield return .35f;Directory.CreateDirectory("Temp/T5Polish");ScreenCapture.CaptureScreenshot("Temp/T5Polish/"+file+".png");yield return .3f;}
        static IEnumerator Flow(){
            Status="Book and method identification";session.Initialize(314159);ArchiveTopicUI.Current.Close();Move(Vector3.zero);yield return .7f;var book=station.GetComponentInChildren<ArchiveAnimatedBook>();
            Check(book!=null&&book.OpenAmount<.01f,"Existing T5 Book starts closed");Check(!State.timerRunning&&State.timerAttempt==0&&Mathf.Abs(session.TimerRemaining(State)-360)<.01f,"Arrival does not start the six-minute clock");ArchiveTopicUI.Current.Open(station);yield return .15f;Check(ui.IsOpen&&!State.timerRunning,"Preview reader leaves the shared clock stopped");ArchiveTopicUI.Current.Close();Book();yield return .8f;double deadline=State.timerDeadline;
            Check(State.phase==1&&State.timerRunning&&State.timerAttempt==1&&State.timerActor==-1&&session.TimerRemaining(State)>358,"Native Book starts T5's shared six-minute timer");Check(book.OpenAmount>.98f,"Existing Book opens and floats while T5 runs");Check(station.points.Count(p=>p.role==ArchivePointRole.Select)==3&&art.TokenRoots.Length==0,"Identify stage has three method altars and no unnecessary tablets");
            var q=session.Question(4);Check(!ui.CheckButton.interactable,"Unselected method cannot be submitted accidentally");ui.SelectItem(-3);yield return .1f;Check(ui.ReadingText.text.Contains("¬Q")&&State.selection==-1,"Method guide explains contrapositive without sending an answer");
            ArchiveTopicUI.Current.Close();yield return .1f;var corners=new Vector3[4];ui.Objective.GetWorldCorners(corners);Check(ui.IsObjectiveVisible&&corners.Min(p=>p.x)>Screen.width*.60f&&corners.Max(p=>p.x)<=Screen.width+1,"Compact T5 objective fits the right side");
            Move(new Vector3(0,0,-5));int revision=State.revision;session.Request(4,ArchiveAction.Select,q.method);yield return .1f;Check(State.revision==revision&&State.selection==-1,"Authority rejects method selection far from its physical altar");
            yield return Preview("T5_MethodAltars",false);yield return Preview("T5_ProblemReader",true);ArchiveTopicUI.Current.Close();yield return Method((q.method+1)%3);yield return Submit();Check(State.round==0&&session.State.mistakes.Count==1&&session.State.mistakes[0].actor==-1&&State.lastAnswerResult==-1,"Wrong method records exactly one submitting-player mistake");Check(State.timerDeadline==deadline&&string.IsNullOrEmpty(State.reveal),"Wrong method preserves the deadline and hides solved explanation");
            int method=State.selection;State.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return .3f;Check(State.timerExpired&&State.phase==0&&State.selection==method&&State.round==0,"Identification timeout preserves the team's selected method");Check(session.State.mistakes.Count==2&&session.State.mistakes.Last().reason=="timeout","Timeout adds exactly one attributed mistake");yield return .3f;Check(session.State.mistakes.Count==2,"Expired clock does not repeatedly charge mistakes");Book();yield return .2f;Check(State.timerAttempt==2&&State.selection==method&&session.TimerRemaining(State)>359,"Book retry retains selected method and starts a new attempt");yield return Method(q.method);yield return 1.6f;yield return Submit();Check(State.round==1&&State.phase==0&&State.reveal.Contains(q.trial.explanation),"Correct method publishes the original explanation only after success");
            deadline=State.timerDeadline;Check(session.ActiveTopic==4&&Enumerable.Range(0,10).Where(t=>t!=4).All(t=>!session.CanStartTopic(t)),"T5 reserves the team topic across Book gates");Book();yield return .2f;q=session.Question(4);Check(q.trial.kind==TrialProofKind.ArrangeSteps&&station.points.All(p=>p.role!=ArchivePointRole.Select)&&State.selection==-1,"Assigned direct proof has no redundant method choice");
            var answer=ArchiveTopicChecks.Solution(q).placements;yield return Place(answer[0],0);yield return Place(answer[1],1);var partial=State.placements.ToArray();State.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return .3f;Check(State.timerExpired&&State.round==1&&State.placements.SequenceEqual(partial),"Direct-proof timeout keeps completed identification and current tablets");Book();yield return .2f;Check(State.placements.SequenceEqual(partial)&&State.timerAttempt==3,"Book retry keeps the original partial proof");
            var json=JsonUtility.ToJson(session.State);typeof(ArchiveTopicSession).GetMethod("Receive",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(session,new object[]{json,true});yield return .12f;Check(State.placements.SequenceEqual(partial)&&State.timerAttempt==3&&session.ActiveTopic==4,"Checkpoint restores the proof arrangement, timer attempt and reservation");
            yield return Arrange(answer.Reverse().ToArray());var ids=art.TokenRoots.Select(t=>t.GetInstanceID()).ToArray();int before=session.State.mistakes.Count;deadline=State.timerDeadline;yield return Submit();Check(State.round==1&&session.State.mistakes.Count==before+1&&ids.SequenceEqual(art.TokenRoots.Select(t=>t.GetInstanceID()))&&State.timerDeadline==deadline,"Incorrect order retains exact tablet objects, work and deadline");yield return Arrange(answer);yield return 1.6f;yield return Submit();Check(State.round==2&&State.reveal.Contains(q.trial.tablets.Last().statement),"Assigned direct proof succeeds without an unused method selection");
            Status="Contrapositive and contradiction";Book();yield return .2f;q=session.Question(4);Check(q.trial.station==TrialProofMethod.Contrapositive&&station.points.All(p=>p.role!=ArchivePointRole.Select),"Contrapositive stage uses the authored station field, not an unused default answer");revision=State.revision;Move(ArchiveMethodPresentation.MethodPosition(1));session.Request(4,ArchiveAction.Select,1);yield return .1f;Check(State.revision==revision,"Assigned ordering stage rejects extraneous method changes");
            for(int i=0;i<q.items.Length;i++){ui.SelectItem(i);Check(ui.ReadingText.text.Contains(q.trial.tablets[i].statement)&&ui.ReadingText.text.Contains(q.trial.tablets[i].justification),"Reader preserves full statement and justification for "+q.items[i]);}
            yield return Preview("T5_ProofTablets",false);yield return Preview("T5_TabletReader",true);ui.SelectItem(0);yield return .25f;ScreenCapture.CaptureScreenshot("Temp/T5Polish/T5_TabletReader.png");yield return .3f;ArchiveTopicUI.Current.Close();yield return Arrange(ArchiveTopicChecks.Solution(q).placements);yield return Submit();Check(State.round==3&&State.reveal.Contains("Contrapositive")&&State.timerDeadline==deadline,"Contrapositive completion shares proof and retains the same running clock");
            Check(State.placements.Length==0&&State.selection==-1,"Book gate clears solved answer IDs while keeping its published proof");State.timerDeadline=ArchiveTopicSession.TimerClock-.01;before=session.State.mistakes.Count;yield return .3f;Check(State.timerExpired&&State.round==3&&State.placements.Length==0&&session.State.mistakes.Count==before+1,"Timeout between challenges retains progress without inheriting the previous answer");
            Book();yield return .2f;q=session.Question(4);Check(State.placements.Length==5&&State.placements.All(p=>p==-1)&&State.timerAttempt==4,"Book starts the next unattempted proof with five empty sockets after gate timeout");Move(station.CurrentItemPosition(0,q,State));restriction=new GameObject("T5 movement restriction fixture");Player.LocalInstance.AcquireMovementLock(restriction,"T5 capture validation",Player.LocalInstance.transform.position,100);revision=State.revision;session.Request(4,ArchiveAction.Pick,0);yield return .12f;Check(!session.CanAct(-1)&&State.revision==revision&&!ui.IsObjectiveVisible,"Existing capture/stun lock rejects a valid nearby tablet pickup and hides UI");Player.LocalInstance.ReleaseMovementLock(restriction);UnityEngine.Object.Destroy(restriction);restriction=null;
            yield return Arrange(ArchiveTopicChecks.Solution(q).placements);yield return Submit();Check(State.round==4&&State.reveal.Contains("Contradiction")&&State.reveal.Contains(q.trial.explanation),"Contradiction proof publishes its original explanation");
            Status="Choose and build";Book();yield return .2f;q=session.Question(4);Check(q.trial.kind==TrialProofKind.ChooseAndArrange&&station.points.Count(p=>p.role==ArchivePointRole.Select)==3&&q.items.Length==5,"Final proof requires both a method and all five authored tablets");yield return Arrange(ArchiveTopicChecks.Solution(q).placements);yield return Method((q.method+1)%3);before=session.State.mistakes.Count;yield return Submit();Check(State.round==4&&session.State.mistakes.Count==before+1,"Correct tablet order with wrong strategy is rejected once");
            partial=State.placements.ToArray();method=State.selection;State.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return .3f;Check(State.timerExpired&&State.placements.SequenceEqual(partial)&&State.selection==method&&State.round==4,"Final timeout keeps all five tablets and selected strategy");Book();yield return .2f;Check(State.timerAttempt==5&&State.placements.SequenceEqual(partial)&&State.selection==method,"Final retry retains both parts of the team's answer");yield return Method(q.method);yield return 1.6f;yield return Submit();
            Check(State.phase==2&&State.round==5&&!State.timerRunning&&session.ActiveTopic==-1,"All five T5 challenges complete, freeze time and unlock the next topic");Check(State.reveal.Contains(q.trial.explanation),"Final accepted proof includes the original method explanation");float remaining=session.TimerRemaining(State);yield return .2f;Check(session.TimerRemaining(State)==remaining,"Completed T5 clock remains frozen");Check(session.State.stations.Where(s=>s.topic!=4).All(s=>s.round==0&&s.timerAttempt==0),"T5 preserves all other topic progress and clocks");Check(!Player.LocalInstance.IsMovementLocked&&Time.timeScale==1&&report.errors.Count==0,"Reading never movement-locks the player or pauses gameplay; no runtime errors");Status="Passed";
        }
        [MenuItem("Tools/Logic Legends/Open Archive/Topics/Validate T5 Proof Variants")]
        public static string ValidateVariants(){
            var source=AssetDatabase.LoadAssetAtPath<ArchiveTopicCatalog>(ArchiveTopicSetup.Folder+"/Archive_Topic_Catalog.asset");var copy=UnityEngine.Object.Instantiate(source);var trials=ScriptableObject.CreateInstance<DirectIndirectProofCatalog>();copy.proofMethods=trials;
            var checks=new List<Result>();var failures=new List<string>();int variants=0,orders=0;
            Action<bool,string> test=(passed,name)=>{checks.Add(new Result{name=name,passed=passed});if(!passed)failures.Add(name);};
            try{for(int r=0;r<5;r++)for(int v=0;v<source.proofMethods.variantSets[r].variants.Length;v++){
                string id="Challenge "+(r+1)+" / variant "+(v+1);trials.variantSets=source.proofMethods.variantSets.Select(set=>new TrialProofVariantSet{variants=new[]{set.variants[0]}}).ToArray();trials.variantSets[r].variants=new[]{source.proofMethods.variantSets[r].variants[v]};var q=ArchiveTopicQuestions.Build(copy,4,r,314159);var good=ArchiveTopicChecks.Solution(q);string message;variants++;
                test(ArchiveTopicQuestions.Validate(q,good,out message),id+" accepts original solution");test(ArchiveTopicQuestions.MethodReveal(q,good).Contains(q.trial.explanation),id+" reveals original explanation only through accepted result");
                test(q.details.SequenceEqual(q.trial.tablets.Select(t=>t.statement+"\n"+t.justification)),id+" preserves all original statements and justifications");
                var points=Enumerable.Range(0,q.items.Length).Select(i=>ArchiveMethodPresentation.TokenPosition(i,q)).ToArray();var sockets=Enumerable.Range(0,q.slots.Length).Select(i=>ArchiveMethodPresentation.SocketPosition(i,q)).ToArray();test(points.Distinct().Count()==points.Length&&points.All(p=>new Vector2(p.x,p.z).magnitude<8)&&sockets.Distinct().Count()==sockets.Length,id+" fits distinct pickup and socket positions inside the forge");
                if(ArchiveMethodPresentation.NeedsMethod(q)){var bad=ArchiveTopicChecks.Solution(q);bad.selection=(q.method+1)%3;test(!ArchiveTopicQuestions.Validate(q,bad,out message),id+" rejects a wrong method");bad.selection=-1;test(!ArchiveTopicQuestions.Validate(q,bad,out message),id+" requires an explicit method choice");}
                else{var noChoice=ArchiveTopicChecks.Solution(q);noChoice.selection=-1;test(ArchiveTopicQuestions.Validate(q,noChoice,out message),id+" does not require selection for assigned method");test(ArchiveTopicQuestions.MethodReveal(q,noChoice).Contains(ArchiveMethodPresentation.MethodName((int)q.trial.station)),id+" shows the original assigned station method");}
                foreach(var order in q.trial.acceptedOrders){var candidate=ArchiveTopicChecks.Solution(q);candidate.placements=order.tabletIds.ToArray();test(ArchiveTopicQuestions.Validate(q,candidate,out message),id+" accepts authored order "+orders);orders++;}
                if(q.items.Length>0){var bad=ArchiveTopicChecks.Solution(q);Array.Reverse(bad.placements);test(!ArchiveTopicQuestions.Validate(q,bad,out message),id+" rejects invalid order");bad.placements=good.placements.ToArray();bad.placements[0]=bad.placements[1];test(!ArchiveTopicQuestions.Validate(q,bad,out message),id+" rejects repeated physical tablet");}
                test(!ArchiveMethodPresentation.Problem(q).Contains("drag")&&!ArchiveMethodPresentation.Problem(q).Contains("on its board"),id+" replaces solo drag-board instructions with physical interaction wording");
            }}catch(Exception e){failures.Add(e.ToString());}finally{UnityEngine.Object.DestroyImmediate(trials);UnityEngine.Object.DestroyImmediate(copy);}
            var data=new{passed=failures.Count==0,variants=variants,acceptedOrders=orders,checks=checks,failures=failures};Directory.CreateDirectory(ArchiveTopicSetup.Folder+"/Testing/Reports");File.WriteAllText(ArchiveTopicSetup.Folder+"/Testing/Reports/T5ProofVariants.json",Newtonsoft.Json.JsonConvert.SerializeObject(data,Newtonsoft.Json.Formatting.Indented));return(data.passed?"Passed":"Failed")+": "+variants+" variants, "+checks.Count+" checks";
        }
        static void Finish(bool success){active=false;EditorApplication.update-=Tick;Application.logMessageReceived-=Log;stack.Clear();if(restriction!=null){Player.LocalInstance.ReleaseMovementLock(restriction);UnityEngine.Object.Destroy(restriction);}if(session!=null&&Application.isPlaying){session.hunting.enabled=oldHunting;session.hunting.Request(LogicLegends.OpenArchive.Hunting.KhezuCommand.Sleep);ArchiveTopicUI.Current.Close();}report.passed=success&&report.errors.Count==0&&report.checks.All(c=>c.passed);Status=report.passed?"Passed":"Failed";Directory.CreateDirectory(ArchiveTopicSetup.Folder+"/Testing/Reports");File.WriteAllText(ArchiveTopicSetup.Folder+"/Testing/Reports/T5PolishPlayMode.json",JsonUtility.ToJson(report,true));Debug.Log("T5 Proof Forge: "+Status+", "+report.checks.Count+" checks");}
    }
